/*
 * Does the download the extension page points at actually exist?
 *
 * It did not, in production, for as long as the page has existed. The zip is
 * generated by a `prebuild` npm lifecycle hook — and vercel.json set
 * buildCommand to "next build --webpack", which runs next directly and never
 * triggers an npm hook. So the file was built on every developer's machine,
 * gitignored so it was never committed, and absent from every deployment. The
 * page linked to it and the browser answered 404.
 *
 * This asserts the two things that were each independently enough to break it:
 * the build command still reaches the generator, and the generator still puts
 * the file where the page looks for it.
 */
import { readFile, stat } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const failures = [];

const vercel = JSON.parse(await readFile(path.join(root, "vercel.json"), "utf8"));
const buildCommand = vercel.buildCommand ?? "";
if (!/prebuild|build-extension-zip/.test(buildCommand)) {
  failures.push(
    `vercel.json buildCommand does not reach the extension zip generator: ${JSON.stringify(buildCommand)}.\n` +
    `    An npm lifecycle hook only fires for "npm run build"; a bare "next build" skips it.`,
  );
}

const { EXTENSION_DOWNLOAD_PATH } = { EXTENSION_DOWNLOAD_PATH: "/sartho-extension.zip" };
const served = path.join(root, "public", EXTENSION_DOWNLOAD_PATH.replace(/^\//, ""));
try {
  const info = await stat(served);
  if (info.size < 1024) failures.push(`${EXTENSION_DOWNLOAD_PATH} exists but is ${info.size} bytes — that is not an extension.`);
} catch {
  failures.push(`${EXTENSION_DOWNLOAD_PATH} is missing from public/. Run: npm run extension:zip`);
}

const source = await readFile(path.join(root, "lib", "extension.ts"), "utf8");
const declared = source.match(/EXTENSION_DOWNLOAD_PATH\s*=\s*"([^"]+)"/)?.[1];
if (declared !== EXTENSION_DOWNLOAD_PATH) {
  failures.push(`lib/extension.ts points at ${declared}, this check verifies ${EXTENSION_DOWNLOAD_PATH}. One of them is wrong.`);
}

if (failures.length) {
  console.error("Extension download is broken:\n" + failures.map((line) => `  - ${line}`).join("\n"));
  process.exit(1);
}
console.log(`Extension download OK — ${EXTENSION_DOWNLOAD_PATH} is built and the build command reaches the generator.`);
